Do not provide any other text or markdown fences.

Here is the original GNU C++17 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

const int MAX_SIZE = (1 << 19) + 5;
int N, K, MOD, MAX_VAL, POPCNT[MAX_SIZE], F[MAX_SIZE];
int A[20][MAX_SIZE], B[20][MAX_SIZE], C[20][MAX_SIZE];
long long MOD_SQUARED;
long long WORK[20][MAX_SIZE];
long long FACTORIAL[MAX_SIZE], INV_FACTORIAL[MAX_SIZE];

long long power_mod(long long base, long long exponent) {
    long long result = 1;
    base %= MOD;
    while (exponent) {
        if (exponent & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exponent >>= 1;
    }
    return result;
}

void setup_factorials() {
    FACTORIAL[0] = 1;
    for (int i = 1; i <= MAX_VAL; ++i)
        FACTORIAL[i] = FACTORIAL[i-1] * i % MOD;
    INV_FACTORIAL[MAX_VAL] = power_mod(FACTORIAL[MAX_VAL], MOD - 2);
    for (int i = MAX_VAL - 1; i >= 0; --i)
        INV_FACTORIAL[i] = INV_FACTORIAL[i+1] * (i+1) % MOD;
}

int next_power_of_two(int x) {
    int p = 1;
    while (p < x) p <<= 1;
    return p;
}

void fast_walsh_transform(int *data, int length, bool is_inverse = false) {
    static long long temp[MAX_SIZE];
    for (int i = 0; i < length; ++i) temp[i] = data[i];

    if (is_inverse) {
        for (int block = 1; block < length; block <<= 1) {
            for (int i = 0; i < length; i += block << 1) {
                for (int j = 0; j < block; ++j) {
                    temp[i + block + j] = (temp[i + block + j] - temp[i + j]) % MOD;
                }
            }
        }
    } else {
        for (int block = 1; block < length; block <<= 1) {
            for (int i = 0; i < length; i += block << 1) {
                for (int j = 0; j < block; ++j) {
                    temp[i + block + j] = (temp[i + block + j] + temp[i + j]) % MOD;
                }
            }
        }
    }

    for (int i = 0; i < length; ++i) {
        data[i] = (int)(temp[i] % MOD);
        if (data[i] < 0) data[i] += MOD;
    }
}

inline void normalize(long long &value) {
    if (value >= MOD_SQUARED) value -= MOD_SQUARED;
}

void transform_multiply() {
    for (int i = 0; i <= 19; ++i) {
        memset(A[i], 0, sizeof(int[MAX_VAL + 1]));
        memset(WORK[i], 0, sizeof(long long[MAX_VAL + 1]));
    }

    for (int i = 0; i <= MAX_VAL; ++i)
        A[POPCNT[i]][i] = F[i];

    for (int i = 0; i <= 19; ++i)
        fast_walsh_transform(A[i], MAX_VAL + 1);

    for (int i = 0; i <= 19; ++i)
        for (int j = 0; i + j <= 19; ++j)
            for (int idx = 0; idx <= MAX_VAL; ++idx)
                normalize(WORK[i + j][idx] += 1LL * A[i][idx] * B[j][idx]);

    for (int i = 0; i <= 19; ++i)
        for (int idx = 0; idx <= MAX_VAL; ++idx)
            C[i][idx] = (int)(WORK[i][idx] % MOD);

    for (int i = 0; i <= 19; ++i)
        fast_walsh_transform(C[i], MAX_VAL + 1, true);

    for (int i = 0; i <= MAX_VAL; ++i)
        F[i] = C[POPCNT[i]][i];
}

void transform_square() {
    static int buffer[20][MAX_SIZE];
    for (int i = 0; i <= 19; ++i)
        memset(WORK[i], 0, sizeof(long long[MAX_VAL + 1]));

    for (int i = 0; i <= 19; ++i)
        for (int j = 0; i + j <= 19; ++j)
            for (int idx = 0; idx <= MAX_VAL; ++idx)
                normalize(WORK[i + j][idx] += 1LL * B[i][idx] * B[j][idx]);

    for (int i = 0; i <= 19; ++i)
        for (int idx = 0; idx <= MAX_VAL; ++idx)
            buffer[i][idx] = (int)(WORK[i][idx] % MOD);

    for (int i = 0; i <= 19; ++i)
        fast_walsh_transform(buffer[i], MAX_VAL + 1, true);

    for (int i = 0; i <= 19; ++i)
        memset(B[i], 0, sizeof(int[MAX_VAL + 1]));

    for (int idx = 0; idx <= MAX_VAL; ++idx)
        B[POPCNT[idx]][idx] = buffer[POPCNT[idx]][idx];

    for (int i = 0; i <= 19; ++i)
        fast_walsh_transform(B[i], MAX_VAL + 1);
}

int main() {
    scanf("%d%d%d", &N, &K, &MOD);
    MOD_SQUARED = 1LL * MOD * MOD;

    if (N & 1) {
        printf("%lld", power_mod(K, N));
        return 0;
    }

    F[0] = 1;
    MAX_VAL = next_power_of_two(N + 1) - 1;
    setup_factorials();

    for (int i = 0; i <= MAX_VAL; ++i)
        POPCNT[i] = __builtin_popcount(i);

    for (int i = 0; i <= MAX_VAL; ++i)
        B[POPCNT[i]][i] = INV_FACTORIAL[i];

    for (int i = 0; i <= 19; ++i)
        fast_walsh_transform(B[i], MAX_VAL + 1);

    int original_k = K;
    while (K) {
        if (K & 1) transform_multiply();
        K >>= 1;
        if (K) transform_square();
    }

    long long answer = (power_mod(original_k, N) - FACTORIAL[N] * F[N] % MOD + MOD) % MOD;
    printf("%lld", answer);
    return 0;
}
